function icon(name) { return Lucide[name] || ""; }

// Create a styled icon element
function iconEl(name, cls = "") {
  const span = document.createElement("span");
  span.className = "icon-lucide " + cls;
  span.innerHTML = icon(name);
  return span;
}

// Table pagination helper
function paginate(rows, page, pageSize) {
  const start = (page - 1) * pageSize;
  return rows.slice(start, start + pageSize);
}

// Render a paginated table into a container
function renderTable(container, { columns, rows, page = 1, pageSize = 15, rowRenderer, onPageChange }) {
  const total = rows.length;
  const pages = Math.max(1, Math.ceil(total / pageSize));
  const pageData = paginate(rows, page, pageSize);
  container.innerHTML = "";
  const wrap = document.createElement("div");
  wrap.className = "table-wrap";
  const table = document.createElement("table");
  table.className = "data";
  const thead = document.createElement("thead");
  const tr = document.createElement("tr");
  columns.forEach((c) => {
    const th = document.createElement("th");
    th.textContent = c.label;
    if (c.width) th.style.width = c.width;
    tr.appendChild(th);
  });
  thead.appendChild(tr);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  pageData.forEach((row, i) => rowRenderer(tbody, row, i));
  table.appendChild(tbody);
  wrap.appendChild(table);
  container.appendChild(wrap);

  // pagination bar
  const bar = document.createElement("div");
  bar.style.display = "flex";
  bar.style.justifyContent = "space-between";
  bar.style.alignItems = "center";
  bar.style.marginTop = "10px";
  bar.style.fontSize = "13px";
  bar.style.color = "var(--muted)";
  bar.innerHTML = "<div>Showing <b>" + (pageData.length ? ((page - 1) * pageSize + 1) : 0) + "</b> to <b>" + Math.min(page * pageSize, total) + "</b> of <b>" + total + "</b> entries</div>" +
    "<div style='display:flex;align-items:center;gap:6px;'>" +
    "<button class='small secondary' " + (page <= 1 ? "disabled" : "") + " data-page='" + (page - 1) + "'>Previous</button>" +
    "<span style='padding:0 6px;'>Page " + page + " of " + pages + "</span>" +
    "<button class='small secondary' " + (page >= pages ? "disabled" : "") + " data-page='" + (page + 1) + "'>Next</button>" +
    "</div>";
  bar.querySelectorAll("button[data-page]").forEach((b) => {
    b.addEventListener("click", () => onPageChange(Number(b.dataset.page)));
  });
  container.appendChild(bar);
}

// Modal helper
function openModal({ title, bodyHtml, footHtml, onShow }) {
  const backdrop = document.createElement("div");
  backdrop.className = "backdrop";
  backdrop.innerHTML =
    '<div class="modal">' +
    '<div class="modal-head"><h3>' + escapeHtml(title) + '</h3><button class="modal-close" aria-label="Close">&times;</button></div>' +
    '<div class="modal-body">' + bodyHtml + '</div>' +
    (footHtml ? '<div class="modal-foot">' + footHtml + '</div>' : '') +
    '</div>';
  document.body.appendChild(backdrop);
  requestAnimationFrame(() => backdrop.classList.add("open"));
  const close = () => {
    backdrop.classList.remove("open");
    setTimeout(() => backdrop.remove(), 250);
  };
  backdrop.querySelector(".modal-close").onclick = close;
  backdrop.onclick = (e) => { if (e.target === backdrop) close(); };
  document.addEventListener("keydown", function esc(e) { if (e.key === "Escape") { close(); document.removeEventListener("keydown", esc); } });
  if (onShow) onShow(backdrop.querySelector(".modal-body"), backdrop.querySelector(".modal-foot"));
  return backdrop;
}
